//! Character references (HTML §13.5 and the character reference states of
//! §13.2.5).
//!
//! - [`data`]: the named character references table, generated by `cargo
//!   xtask tables` from the vendored `entities.json`.
//! - [`spec`]: the matching rule of the named character reference state
//!   and the numeric character reference end state's rules.
//! - [`contract`]: what the executable functions are proven to satisfy.
//! - [`exec`]: the executable functions, and their proofs.
//! - [`lemmas`]: facts proven about the spec.
//! - [`examples`]: the standard's examples, evaluated on the spec.

pub mod contract;
pub mod data;
pub mod examples;
pub mod exec;
pub mod index;
pub mod lemmas;
pub mod search;
pub mod spec;
